struct PairingConfigDoc {
    uint32_t version{};
    std::string updated_at{};
    PairingSyncSettings sync{};
    PairingCredentials credentials{};

    void to_c(rrcp_pairing_config_doc_t &c) const {
        rrcp_pairing_config_doc_init(&c);
        c.version = version;
        detail::copy_str(c.updated_at, sizeof c.updated_at, updated_at);
        sync.to_c(c.sync);
        credentials.to_c(c.credentials);
    }
    static PairingConfigDoc from_c(const rrcp_pairing_config_doc_t &c) {
        PairingConfigDoc v;
        v.version = c.version;
        v.updated_at = std::string(c.updated_at);
        v.sync = PairingSyncSettings::from_c(c.sync);
        v.credentials = PairingCredentials::from_c(c.credentials);
        return v;
    }
    std::string to_json() const {
        rrcp_pairing_config_doc_t c;
        to_c(c);
        char buf[8192];
        int n = rrcp_pairing_config_doc_encode(&c, buf, sizeof buf);
        detail::check(n);
        return std::string(buf, static_cast<size_t>(n));
    }
    static PairingConfigDoc from_json(std::string_view json) {
        rrcp_pairing_config_doc_t c;
        detail::check(rrcp_pairing_config_doc_decode(json.data(), json.size(), &c));
        return from_c(c);
    }
};

